constraints:
1 ≤ Number of nodes ≤ 10^{5}
0 ≤ Data of a node ≤ 10^{5}

expected time complexity: O(N).
expected auxiliary space: O(H).

standard_solution_code:
class Solution:

	def _solve(self, node):
		if not node:
			return None
		left = self._solve(node.left)
		right = self._solve(node.right)
		if left:
			while left.right:
				left = left.right
			left.right = node
			node.left = left
		if right:
			while right.left:
				right = right.left
			right.left = node
			node.right = right
		while node.right:
			node = node.right
		return node

	def bToDLL(self, root):
		if not root:
			return None
		head = self._solve(root)
		while head.left:
			head = head.left
		return head
